function rfTranscriptSection(string $subject,string $transcript):?array{$t=trim(preg_replace('/\s+/',' ',$transcript)??'');if($t==='')return null;$sent=preg_split('/(?<=[.!?])\s+/',$t)?:[];$sent=array_values(array_filter(array_map('trim',$sent)));$terms=array_slice(rfTranscriptWords($t),0,10);$body="The available YouTube captions provide additional source context for $subject. The transcript contains recurring terms such as ".htmlspecialchars(implode(', ',$terms),ENT_QUOTES,'UTF-8').". These terms help identify the language used in the video without assuming details that are not actually present in the source. Caption text can miss tone, visuals, timing or speaker identity, so important meaning should still be checked against the complete video.";return ['heading'=>'What the available transcript adds','body'=>$body,'sample'=>implode(' ',array_slice($sent,0,2))];}
